// StackSidebar — Gtk.StackSidebar
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles stacksidebar with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"

export interface StackSidebarProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** Stack, from Gtk.StackSidebar */
  stack?: ReactNode
}

export function StackSidebar({ className, children }: StackSidebarProps) {
  return (
    <div className={cn(className)}>
      {children}
    </div>
  )
}
